/* Merges window.NEWS_AUTO into window.MARKET_DATA in place, de-duplicating by url/title.
 * Call this AFTER xauusd-data.js and news-auto.js are both loaded, BEFORE app.js reads D.
 * Curated (hand-written) rows are preserved; the previous auto:true snapshot is replaced by the new one
 * so index.html/app.js can badge them differently if desired. */
window.mergeNewsAuto = function () {
  var D = window.MARKET_DATA, A = window.NEWS_AUTO;
  if (!D || !A) return;
  function replaceAuto(list, extra, key) {
    var base = (list || []).filter(function (x) { return !x.auto; });
    var seen = {}; base.forEach(function (x) { if (x[key]) seen[x[key]] = 1; });
    return base.concat((extra || []).filter(function (x) { return x[key] && !seen[x[key]]; }));
  }
  D.incoming = replaceAuto(D.incoming, A.incoming, "event");
  (D.tabs || []).forEach(function (T) {
    var by = A.byTab[T.id]; if (!by) return;
    T.news = replaceAuto(T.news, by.news, "title");
    T.speakers = replaceAuto(T.speakers, by.speakers, "quote");
  });
};
if (window.MARKET_DATA) window.mergeNewsAuto();
